      "date": "2026-07-18",
      "note": "Phase 5: retain exactly one known-good previous canonical DuckDB generation until the next successful publish. Remove that backup only before constructing the next candidate, keeping canonical-store peak usage near two generations plus staged artifacts.",
      "adr_candidate": false
    },
